import numpy as np, ot
from scipy.optimize import linear_sum_assignment

def same(n, seed):
    np.random.seed(seed)
    a = ot.utils.unif(n)
    M = np.random.rand(n,n)
    G_ref = ot.lp.emd(a, a, M, check_marginals=False)
    row, col = linear_sum_assignment(M)
    G = np.zeros_like(M)
    G[row, col] = 1.0/n
    return np.allclose(G_ref, G)
for n in range(2,10):
    for seed in range(5):
        if not same(n, seed):
            print('Mismatch n', n, 'seed', seed)
            raise SystemExit
print('All equal for n<10 seeds<5')
